/**
 * Differential test: our TypeScript CAS parsers vs casparser 1.4.1 (the Python oracle).
 * Fixtures are synthetic, encrypted PDFs generated by fixtures/generate_cas_fixtures.py;
 * fixtures/expected/*.json is casparser's output for the same files (dump_oracle.py).
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { getDocument, OPS } from 'pdfjs-dist/legacy/build/pdf.mjs';
import { Dec, parseCas, PDF_PAGE_EXTRACTOR_JS, UnsupportedStatementError, type DepositoryCasData, type ExtractedPage, type RtaCasData } from '../src/cas';

// The exact source string the app injects into its WebView.
// eslint-disable-next-line @typescript-eslint/no-implied-eval
const extractPage = new Function(`return ${PDF_PAGE_EXTRACTOR_JS}`)() as (ops: typeof OPS, page: unknown) => Promise<ExtractedPage>;

const fixture = (path: string) => fileURLToPath(new URL(`./fixtures/${path}`, import.meta.url));

async function loadPages(name: string, password = 'ABCDE1234F'): Promise<ExtractedPage[]> {
  const data = new Uint8Array(readFileSync(fixture(`pdf/${name}`)));
  const task = getDocument({ data, password, verbosity: 0 });
  const doc = await task.promise;
  const pages: ExtractedPage[] = [];
  for (let i = 1; i <= doc.numPages; i++) pages.push(await extractPage(OPS, await doc.getPage(i)));
  await task.destroy();
  return pages;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const expected = (name: string): any => JSON.parse(readFileSync(fixture(`expected/${name}.json`), 'utf8'));

/** Numeric equality (casparser prints Decimal("0") where a scale-3 zero was parsed, etc.). */
function num(actual: Dec | null, oracle: string | null): void {
  if (oracle === null) {
    expect(actual).toBeNull();
    return;
  }
  expect(actual, `expected ${oracle}`).not.toBeNull();
  expect(actual?.cmp(Dec.parse(oracle) as Dec), `${actual} vs ${oracle}`).toBe(0);
}

describe.each(['cams_detailed', 'kfin_detailed'])('RTA detailed CAS: %s', (name) => {
  it('matches casparser field by field', async () => {
    const actual = parseCas(await loadPages(`${name}.pdf`)) as RtaCasData;
    const oracle = expected(name);
    expect(actual.kind).toBe('rta_detailed');
    expect(actual.fileType).toBe(oracle.file_type);
    expect(actual.statementPeriod).toEqual(oracle.statement_period);
    expect(actual.warnings, actual.warnings.join("\n")).toHaveLength(oracle.parse_warnings.length);
    expect(actual.folios).toHaveLength(oracle.folios.length);

    oracle.folios.forEach((of: any, fi: number) => {
      const f = actual.folios[fi]!;
      expect({ folio: f.folio, amc: f.amc, name: f.name, pan: f.pan, kyc: f.kyc, panKyc: f.panKyc }).toEqual({
        folio: of.folio, amc: of.amc, name: of.name, pan: of.PAN, kyc: of.KYC, panKyc: of.PANKYC,
      });
      expect(f.schemes).toHaveLength(of.schemes.length);
      of.schemes.forEach((os: any, si: number) => {
        const s = f.schemes[si]!;
        expect({ scheme: s.scheme, advisor: s.advisor, rtaCode: s.rtaCode, rta: s.rta, isin: s.isin, nominees: s.nominees }).toEqual({
          scheme: os.scheme, advisor: os.advisor, rtaCode: os.rta_code, rta: os.rta, isin: os.isin, nominees: os.nominees,
        });
        num(s.open, os.open);
        num(s.close, os.close);
        num(s.closeCalculated, os.close_calculated);
        expect(s.valuation.date).toBe(os.valuation.date);
        num(s.valuation.nav, os.valuation.nav);
        num(s.valuation.cost, os.valuation.cost);
        num(s.valuation.value, os.valuation.value);
        expect(s.transactions).toHaveLength(os.transactions.length);
        os.transactions.forEach((ot: any, ti: number) => {
          const t = s.transactions[ti]!;
          expect({ date: t.date, description: t.description, type: t.type, giftFolio: t.giftFolio }).toEqual({
            date: ot.date, description: ot.description, type: ot.type, giftFolio: ot.gift_folio,
          });
          num(t.amount, ot.amount);
          num(t.units, ot.units);
          num(t.nav, ot.nav);
          num(t.balance, ot.balance);
          num(t.dividendRate, ot.dividend_rate);
        });
      });
    });
  });
});

describe('CDSL CAS', () => {
  it('matches casparser holdings for every account', async () => {
    const actual = parseCas(await loadPages('cdsl.pdf')) as DepositoryCasData;
    const oracle = expected('cdsl');
    expect(actual.kind).toBe('depository');
    expect(actual.statementPeriod).toEqual(oracle.statement_period);
    expect(actual.accounts).toHaveLength(oracle.accounts.length);
    oracle.accounts.forEach((oa: any, ai: number) => {
      const a = actual.accounts[ai]!;
      expect({ name: a.name, type: a.type, dpId: a.dpId, clientId: a.clientId, folios: a.folios }).toEqual({
        name: oa.name, type: oa.type, dpId: oa.dp_id, clientId: oa.client_id, folios: oa.folios,
      });
      num(a.balance, oa.balance);
      expect(a.owners).toEqual(oa.owners.map((o: any) => ({ name: o.name, pan: o.PAN })));
      expect(a.equities).toHaveLength(oa.equities.length);
      oa.equities.forEach((oe: any, i: number) => {
        const e = a.equities[i]!;
        expect([e.name, e.isin]).toEqual([oe.name, oe.isin]);
        num(e.numShares, oe.num_shares);
        num(e.price, oe.price);
        num(e.value, oe.value);
      });
      expect(a.mutualFunds).toHaveLength(oa.mutual_funds.length);
      oa.mutual_funds.forEach((om: any, i: number) => {
        const m = a.mutualFunds[i]!;
        expect([m.name, m.isin, m.folio, m.ucc]).toEqual([om.name, om.isin, om.folio, om.ucc]);
        num(m.balance, om.balance);
        num(m.nav, om.nav);
        num(m.value, om.value);
        num(m.totalCost, om.total_cost);
        num(m.pnl, om.pnl);
        num(m.returnPct, om.return);
      });
    });
  });
});

describe('CAS error handling', () => {
  it('rejects a wrong password', async () => {
    await expect(loadPages('cams_detailed.pdf', 'WRONGPASS1')).rejects.toThrow(/password/i);
  });

  it('refuses unknown documents instead of guessing', () => {
    const atom = { text: 'Monthly bank statement', chars: [], font: 'f', xLeft: 40, xRight: 140, yTop: 808, yBot: 798, baseline: 800 };
    expect(() => parseCas([{ atoms: [atom], text: 'Monthly bank statement' }])).toThrow(
      UnsupportedStatementError,
    );
  });
});
